package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.ApplicationSessionIdentity;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.function.ThrowingSupplier;
import static com.ruoyi.medical.persistence.ProfessionalCheckService.*;

/** Issue decisions are atomic original operations, not mutable client-authored resolution claims. */
public final class ProfessionalIssueService {
    private final EnterpriseAccess access;private final JdbcTemplate db;private final DocumentReadService documents;private final ResourceReadAuthority resources;
    private final ProfessionalCheckService checks;private final ProfessionalIssueSchema schema;private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema();
    public ProfessionalIssueService(DataSource data,EnterpriseAccess access,DocumentReadService documents,ResourceReadAuthority resources,ProfessionalCheckService checks,ProfessionalIssueSchema schema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.access=access;this.documents=documents;this.resources=resources;this.checks=checks;this.schema=schema;}
    public JsonNode list(ApplicationSessionIdentity.Verified subject,String context,String document,String revision,String status,String severity,String after,int limit)throws Exception{
        WireValues.uuid(document);WireValues.uuid(revision);if(after!=null)WireValues.uuid(after);if(limit<1||limit>100)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);
        if(status!=null&&!Set.of("OPEN","IN_PROGRESS","RESOLVED","REOPENED").contains(status))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);if(severity!=null&&!Set.of("BLOCKING","WARNING","INFO").contains(severity))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);
        var proof=documents.readFixed(subject,context,document,revision);
        return tx(subject,a->{context(a,context);documents.requireCurrent(a,proof);var h=proof.header();var sql=new StringBuilder("SELECT * FROM issue WHERE tenant_id=? AND project_id=? AND document_revision=?");var args=new ArrayList<Object>(List.of(h.tenantId(),h.projectId(),revision));if(status!=null){sql.append(" AND status=?");args.add(status);}if(severity!=null){sql.append(" AND severity=?");args.add(severity);}if(after!=null){sql.append(" AND issue_id>?");args.add(after);}sql.append(" ORDER BY issue_id LIMIT ? FOR UPDATE");args.add(limit+1);var rows=db.queryForList(sql.toString(),args.toArray());boolean more=rows.size()>limit;if(more)rows=rows.subList(0,limit);var result=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("document_id",document).put("document_revision",revision).put("evidence_watermark",proof.watermarks().evidenceWatermark().toString()).put("issue_watermark",proof.watermarks().issueWatermark().toString()).put("professional_coverage",false);var items=result.putArray("items");for(var row:rows)items.add(item(row,proof));if(more)result.put("next_cursor",str(rows.get(rows.size()-1),"issue_id"));else result.putNull("next_cursor");return schema.result(result);});
    }
    public JsonNode decide(ApplicationSessionIdentity.Verified subject,String context,String issue,String key,byte[] bytes)throws Exception{
        WireValues.uuid(issue);PermissionSchema.revision(context);SimulationInputArtifactSchema.key(key);var request=schema.request(bytes);String hash=json.hash(Map.of("issue_id",issue,"request",request));
        var identity=tx(subject,a->{context(a,context);return issue(a,issue);});String document=str(identity,"document_id");
        var original=documents.readFixed(subject,context,document,str(identity,"document_revision"));
        // Recovery precedes state/CAS checks: an original completed decision is never executed twice.
        var recovered=tx(subject,a->{authorize(a,context,original);return recovery(a,issue,key,hash);});if(recovered!=null)return recovered;
        ProfessionalCheckService.Verified oldCheck=null,newCheck=null;
        if("RESOLVE".equals(text(request,"decision"))){oldCheck=checks.verified(subject,context,str(identity,"check_id"));newCheck=checks.verified(subject,context,text(request,"new_check_id"));}
        var old=oldCheck;var fresh=newCheck;var current=documents.readFixed(subject,context,document,text(request,"document_revision"));
        return tx(subject,a->{authorize(a,context,original);authorize(a,context,current);var replay=recovery(a,issue,key,hash);if(replay!=null)return replay;var r=issue(a,issue);var h=current.header();
            if(!h.documentRevision().equals(h.currentDocumentRevision()))stale();same(document,str(r,"document_id"));same(text(request,"issue_revision"),str(r,"revision"));same(text(request,"evidence_watermark"),current.watermarks().evidenceWatermark().toString());same(text(request,"issue_watermark"),current.watermarks().issueWatermark().toString());
            String decision=text(request,"decision"),status=str(r,"status"),next;String assignee=r.get("assignee_id")==null?null:str(r,"assignee_id");JsonNode resolution=null;
            switch(decision){
                case "ASSIGN"->{if("RESOLVED".equals(status))stale();assignee=text(request,"assignee_id");assignee(a,h,assignee);next="IN_PROGRESS";}
                case "REOPEN"->{if(!"RESOLVED".equals(status))stale();next="REOPENED";}
                case "RESOLVE"->{if("RESOLVED".equals(status)||old==null||fresh==null)stale();old.requireCurrent(a);fresh.requireValid(a);requireResolution(r,current,old,fresh);next="RESOLVED";resolution=json.tree(Map.of("check_id",str(fresh.snapshot().row(),"check_id"),"findings_sha256",fresh.snapshot().objects().get("findings").sha256(),"coverage_sha256",fresh.snapshot().objects().get("coverage").sha256(),"input_sha256",str(fresh.snapshot().row(),"input_sha256"),"document_revision",h.documentRevision(),"evidence_watermark",text(request,"evidence_watermark"),"issue_watermark",text(request,"issue_watermark")));}
                default->throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);
            }
            String id=UUID.randomUUID().toString(),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var at=db.queryForObject("SELECT UTC_TIMESTAMP(6)",LocalDateTime.class);
            if(db.update("UPDATE issue SET status=?,assignee_id=?,resolution_ref=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND issue_id=? AND revision=?",next,assignee,resolution==null?null:json.canonical(resolution),at,h.tenantId(),h.projectId(),issue,text(request,"issue_revision"))!=1)stale();
            var affected=new LinkedHashSet<String>(List.of(h.documentRevision(),str(r,"document_revision")));for(String rev:affected){if(db.update("UPDATE document_revision_state SET issue_watermark=issue_watermark+1,revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND document_revision=?",at,h.tenantId(),h.projectId(),rev)!=1)stale();
                db.update("UPDATE check_run SET invalidation_reason=COALESCE(invalidation_reason,'ISSUE_WATERMARK_CHANGED'),revision=revision+1,updated_at=? WHERE tenant_id=? AND project_id=? AND target_kind='DOCUMENT' AND target_revision=?",at,h.tenantId(),h.projectId(),rev);
            }
            var updated=issue(a,issue);var result=JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("decision_id",id).put("issue_id",issue).put("document_id",document).put("document_revision",h.documentRevision()).put("decision",decision).put("actor_id",a.actorId()).put("decided_at",at.toInstant(java.time.ZoneOffset.UTC).toString()).put("issue_revision",str(updated,"revision")).put("status",next).put("evidence_watermark",current.watermarks().evidenceWatermark().toString()).put("issue_watermark",current.watermarks().issueWatermark().add(java.math.BigInteger.ONE).toString()).put("reason",text(request,"reason")).put("audit_id",audit).put("event_id",event);if(assignee==null)result.putNull("assignee_id");else result.put("assignee_id",assignee);result.set("resolution",resolution==null?com.fasterxml.jackson.databind.node.NullNode.instance:resolution);
            schema.result(result);var saved=meta(a,h,at);saved.putAll(Map.of("decision_id",id,"issue_id",issue,"actor_id",a.actorId(),"idempotency_key",key,"request_sha256",hash,"request_json",json.canonical(request),"result_json",json.canonical(result),"result_sha256",json.hash(result)));insert("professional_issue_decision",saved);
            var log=meta(a,h,at);log.putAll(Map.of("audit_id",audit,"subject_id",a.actorId(),"action","issue.decision.recorded","resource_ref",json.canonical(result),"result","SUCCESS","request_id",id,"trace_id",id));insert("audit_event",log);insert("outbox_event",Map.of("tenant_id",h.tenantId(),"event_id",event,"aggregate_id",issue,"aggregate_revision",str(updated,"revision"),"event_type","issue.decision.recorded","payload",json.canonical(result),"occurred_at",at));return result;
        });
    }
    /** Correlated successful new evidence, not mere disappearance from a filtered list. */
    static void requireResolution(Map<String,Object> issue,DocumentReadService.FixedRead current,ProfessionalCheckService.Verified old,ProfessionalCheckService.Verified fresh){
        same(str(issue,"check_id"),str(old.snapshot().row(),"check_id"));if(str(issue,"check_id").equals(str(fresh.snapshot().row(),"check_id")))stale();same(str(issue,"document_id"),fresh.snapshot().document().header().documentId());same(current.header().documentRevision(),fresh.findings().targetRevision());
        if(!timestamp(fresh.snapshot().row().get("created_at")).isAfter(timestamp(issue.get("updated_at"))))stale();
        var candidates=old.findings().issueProposals().stream().filter(p->{try{return new TaskSourceVerifierSchema().hash(p).equals(str(issue,"finding_sha256"));}catch(Exception e){throw new IllegalStateException(e);}}).toList();var proposal=one(candidates);String node=node(proposal.anchor());
        var nodes=new HashMap<String,InterfaceProtocol.Node>();current.body().nodes().forEach(n->nodes.put(n.nodeId(),n));var ancestors=new HashSet<String>();String cursor=node;while(cursor!=null){if(!ancestors.add(cursor)||!nodes.containsKey(cursor))stale();cursor=nodes.get(cursor).parentId();}
        var rule=fresh.findings().ruleChecks().stream().filter(r->r.ruleId().equals(proposal.ruleId())&&r.targetNodeIds().stream().anyMatch(ancestors::contains)).toList();if(rule.size()!=1||rule.get(0).result()!=ArtifactProtocol.RuleResult.PASS)stale();
        if(fresh.findings().issueProposals().stream().anyMatch(p->p.ruleId().equals(proposal.ruleId())&&node(p.anchor()).equals(node)))stale();
        for(String claim:proposal.claimIds()){
            String mapped=claim;if(!old.findings().targetRevision().equals(fresh.findings().targetRevision())){
                var keys=new ArrayList<String>();old.snapshot().document().body().nodes().forEach(n->keys.add(n.nodeId()));old.snapshot().document().body().fields().forEach(f->keys.add(f.fieldId()));var matches=keys.stream().filter(k->derived(old.findings().targetRevision(),k).equals(claim)).toList();mapped=derived(fresh.findings().targetRevision(),one(matches));
            }
            String required=mapped;var checks=fresh.findings().claimChecks().stream().filter(c->c.claimId().equals(required)).toList();if(checks.size()!=1)stale();var c=checks.get(0);if(c.accessCheck()!=ArtifactProtocol.AccessCheck.PASS||c.locatorCheck()!=ArtifactProtocol.LocatorCheck.PASS||c.supportCheck()!=ArtifactProtocol.SupportCheck.SUPPORTED||!c.ruleIds().contains(proposal.ruleId())||c.readReceiptIds().isEmpty())stale();
        }
    }
    private static String node(ArtifactProtocol.Anchor a){return a instanceof ArtifactProtocol.TextAnchor t?t.nodeId():((ArtifactProtocol.StructuredAnchor)a).nodeId();}
    private static String derived(String rev,String key){return UUID.nameUUIDFromBytes(("N07/"+rev+"/"+key).getBytes(StandardCharsets.UTF_8)).toString();}
    private static LocalDateTime timestamp(Object v){return v instanceof java.sql.Timestamp t?t.toLocalDateTime():(LocalDateTime)v;}
    private void authorize(EnterpriseAccess.Admission a,String c,DocumentReadService.FixedRead proof)throws Exception{context(a,c);documents.requireCurrent(a,proof);var h=proof.header();resources.require(a,new PermissionProtocol.Scope(h.tenantId(),h.projectId(),"DOCUMENT",h.documentId()),"document.review","DOCUMENT_BODY");}
    private void assignee(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,String user){var active=db.queryForList("SELECT user_id FROM tenant_member WHERE tenant_id=? AND user_id=? AND status='ACTIVE' AND valid_from<=UTC_TIMESTAMP(6) AND (valid_to IS NULL OR valid_to>UTC_TIMESTAMP(6)) LIMIT 2 FOR UPDATE",h.tenantId(),user);if(active.size()!=1)throw new TenantAccessException(ErrorCode.ACCESS_DENIED);for(String action:List.of("document.read","document.review")){var grants=db.queryForList("SELECT grant_id FROM permission_grant WHERE tenant_id=? AND subject_id=? AND action=? AND status='ACTIVE' AND valid_from<=UTC_TIMESTAMP(6) AND (valid_to IS NULL OR valid_to>UTC_TIMESTAMP(6)) AND ((resource_kind='ENTERPRISE' AND project_id IS NULL AND resource_id=?) OR (resource_kind='PROJECT' AND project_id=? AND resource_id=?) OR (resource_kind='DOCUMENT' AND project_id=? AND (resource_id IS NULL OR resource_id=?))) LIMIT 1 FOR UPDATE",h.tenantId(),user,action,h.tenantId(),h.projectId(),h.projectId(),h.projectId(),h.documentId());if(grants.isEmpty())throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}}
    private JsonNode recovery(EnterpriseAccess.Admission a,String issue,String key,String hash)throws Exception{var rows=db.queryForList("SELECT * FROM professional_issue_decision WHERE tenant_id=? AND actor_id=? AND idempotency_key=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),a.actorId(),key);if(rows.isEmpty())return null;var row=one(rows);same(issue,str(row,"issue_id"));same(hash,str(row,"request_sha256"));same(schema.manifest(),str(row,"schema_manifest_sha256"));var r=json.read(str(row,"result_json"));same(json.hash(r),str(row,"result_sha256"));same(hash,json.hash(Map.of("issue_id",issue,"request",json.read(str(row,"request_json")))));same(r,json.read(str(one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND audit_id=? AND subject_id=? AND action='issue.decision.recorded' AND result='SUCCESS' LIMIT 2 FOR UPDATE",a.context().tenant_id(),text(r,"audit_id"),a.actorId())),"resource_ref")));same(r,json.read(str(one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='issue.decision.recorded' LIMIT 2 FOR UPDATE",a.context().tenant_id(),text(r,"event_id"),issue)),"payload")));return schema.result(r);}
    private Map<String,Object> issue(EnterpriseAccess.Admission a,String id){return one(db.queryForList("SELECT i.*,m.document_id FROM issue i JOIN document_revision_meta m ON m.tenant_id=i.tenant_id AND m.project_id=i.project_id AND m.document_revision=i.document_revision WHERE i.tenant_id=? AND i.issue_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),id));}
    private JsonNode item(Map<String,Object> row,DocumentReadService.FixedRead proof)throws Exception{var n=JsonNodeFactory.instance.objectNode();for(String k:List.of("issue_id","check_id","document_revision","severity","code","status","revision")){if(row.get(k)==null)n.putNull(k);else n.put(k,str(row,k));}var position=json.read(str(row,"position"));var codec=com.fasterxml.jackson.databind.json.JsonMapper.builder().propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).build();var anchor=codec.treeToValue(position,ArtifactProtocol.Anchor.class);if(!new TaskSourceVerifierNormalizer(json).anchorValid(anchor,json.read(proof.bodyBytes())))bad();n.set("position",position);n.put("location_status",proof.header().documentRevision().equals(proof.header().currentDocumentRevision())?"CURRENT_VERSION":"ORIGINAL_VERSION");if(row.get("assignee_id")==null)n.putNull("assignee_id");else n.put("assignee_id",str(row,"assignee_id"));n.set("resolution",row.get("resolution_ref")==null?com.fasterxml.jackson.databind.node.NullNode.instance:json.read(str(row,"resolution_ref")));return n;}
    private Map<String,Object> meta(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,LocalDateTime at){var r=new LinkedHashMap<String,Object>();r.putAll(Map.of("tenant_id",h.tenantId(),"project_id",h.projectId(),"created_by",a.actorId(),"created_at",at,"classification",h.classification(),"schema_version","1.0.0","schema_manifest_sha256",schema.manifest()));return r;}
    private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
    private <T>T tx(ApplicationSessionIdentity.Verified s,Work<T> w){return access.execute(s,a->ThrowingSupplier.of(()->w.run(a)).get());}private interface Work<T>{T run(EnterpriseAccess.Admission a)throws Exception;}private static void stale(){throw new TenantAccessException(ErrorCode.REVIEW_STALE);}
}
